/* Sparkle Canvas Container for Dashboard */
.dashboard-sparkle-container {
  position: relative;
  background-color: #faf9f5;
  background-image:
    radial-gradient(circle at 15% 15%, rgba(212, 175, 55, 0.08) 0%, transparent 45%),
    radial-gradient(circle at 85% 25%, var(--tenant-sparkle-tint, rgba(236, 72, 153, 0.08)) 0%, transparent 40%),
    radial-gradient(circle at 50% 75%, rgba(255, 255, 255, 0.9) 0%, transparent 70%);
  min-height: 100vh;
  overflow-x: hidden;
}
.dashboard-sparkle-container::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: 
    radial-gradient(2px 2px at 20px 30px, rgba(212, 175, 55, 0.6), rgba(0,0,0,0)),
    radial-gradient(2px 2px at 40px 70px, rgba(255, 255, 255, 0.9), rgba(0,0,0,0)),
    radial-gradient(1.5px 1.5px at 90px 40px, var(--tenant-sparkle-core, rgba(236, 72, 153, 0.7)), rgba(0,0,0,0)),
    radial-gradient(2px 2px at 160px 120px, rgba(212, 175, 55, 0.5), rgba(0,0,0,0)),
    radial-gradient(1.5px 1.5px at 230px 190px, rgba(255, 255, 255, 0.95), rgba(0,0,0,0));
  background-repeat: repeat;
  background-size: 280px 280px;
  opacity: 0.65;
  animation: sparkleGlaze 12s ease-in-out infinite alternate;
  pointer-events: none;
  z-index: 0;
}
@keyframes sparkleGlaze {
  0% { transform: translateY(0px) scale(1); opacity: 0.55; }
  50% { transform: translateY(-6px) scale(1.02); opacity: 0.75; }
  100% { transform: translateY(0px) scale(1); opacity: 0.55; }
}
@media (prefers-reduced-motion: reduce) {
  .dashboard-sparkle-container::before {
    animation: none;
  }
}
